insert into public.trace_bridge_roles (catalogue_version, target_role_id, bridge_role_id, requirements_pack, responsibilities, develops, partly_develops, develops_note, entry_basis, entry_requirements_stated, entry_signal_families, entry_signal_requirements, suitable_backgrounds, suitability_note, tradeoff_note, level_step, source_keys, source_notes, entry_evidence, progression_evidence, may_be_primary, partial_development)
values ('pm-bridges-v2', 'PM-PM', 'PM-APM', 'pm-v1.2', array['Works with product managers to advocate for user needs and prioritise delivery of the greatest value', 'Manages a smaller product with support, or a subset of features of a larger product', 'Learns product management approaches and methods (prioritisation, roadmapping, evidence-based decisions)', 'Works in multidisciplinary teams to plan and deliver product increments']::text[], array['C1', 'C3', 'C5', 'C6']::text[], array['C2', 'C4', 'X5', 'L2']::text[], 'F1 sets the associate level at ''working'' in user-centred insight, product management, stakeholder relationships and agile practice (C1, C3, C5, C6 developed), and at ''awareness'' in strategic ownership, managing product outcomes, value for money and product leadership (C2, C4, X5, L2 only partly).', 'open_entry', 'No formal requirements are stated. F1 says the level ''can be an entry-level role for civil servants who are looking to move into a digital role'' (UK public sector); applying this to other employers is Trace''s reading.', '{}'::text[], '{}'::text[], 'People moving into product work from other roles, including other digital roles; the framework names business analyst and delivery roles among those that share product manager skills.', 'Suits someone whose profile does not yet show several core product management responsibilities: the role gives supervised ownership of features before owning a product.', 'Associate is a more junior level than Product Manager; for an experienced professional it can mean a step down in level before moving up.', false, array['pm-v1:F1']::text[], '{"pm-v1:F1": "Role levels: associate product manager (skills at working and awareness levels; routes in)"}'::jsonb, 'source_stated_context', 'source_stated', true, '{"C2": {"develops": "Roadmapping and prioritisation methods for features or a smaller product (F1: product management, working).", "incomplete": "Ownership of a product''s strategy and direction (F1: strategic ownership, awareness only).", "seek": "Ask to own the roadmap for a feature area and to contribute to the product''s strategy."}, "C4": {"develops": "Recommending evidence-based decisions using insight and data, and awareness of measuring outcomes.", "incomplete": "Defining and owning outcome metrics and deciding from them (F1: managing product outcomes, awareness only).", "seek": "Ask to define and own the success metric of a feature you manage, and to make the follow-up decision."}, "L2": {"develops": "Awareness of product leadership.", "incomplete": "Coaching or leading other product practitioners.", "seek": "Mentor a newer team member on product work."}, "X5": {"develops": "Awareness of value for money.", "incomplete": "Building or owning a business case.", "seek": "Contribute the cost and value analysis to a business case."}}'::jsonb);
insert into public.trace_bridge_roles (catalogue_version, target_role_id, bridge_role_id, requirements_pack, responsibilities, develops, partly_develops, develops_note, entry_basis, entry_requirements_stated, entry_signal_families, entry_signal_requirements, suitable_backgrounds, suitability_note, tradeoff_note, level_step, source_keys, source_notes, entry_evidence, progression_evidence, may_be_primary, partial_development)
values ('pm-bridges-v2', 'PM-PM', 'ROLE-PAN', 'pm-v1.2', array['Analyses product data for product managers, engineers and designers', 'Defines product metrics and builds dashboards that show whether the product is succeeding', 'Finds opportunities in data to improve adoption, retention, engagement or monetisation', 'Helps design, run and evaluate A/B tests on the user journey']::text[], array['C4', 'C5', 'X1']::text[], array['C1', 'X5']::text[], 'Curated reading of the GitLab definition: the analyst is the technical owner of product KPIs, defines the metrics that show success and evaluates experiments with recommendations (C4, under the D35 standard of defining metrics and using them to influence decisions; the decision itself stays with the product manager), works with product teams (C5) and does hands-on analytics (X1). Learning about users is through data only (C1 partly). It does not involve roadmaps (C2), requirements (C3) or delivery (C6).', 'signals', 'Employer-specific (GitLab): 3+ years of data analysis, 2+ years on feature and usage metrics or A/B testing, experience supporting a product team, advanced SQL. Other employers set their own criteria. The move from Product Analyst to Product Manager is not described by the source (a curated hypothesis).', array['data_analytics', 'data_science', 'product_analytics']::text[], array['X1']::text[], 'Data analysis, data science or analytics roles, or any background with demonstrated hands-on analytics.', 'Suits someone with analytics evidence whose gaps are in understanding users and owning outcome metrics: the role works on those with product teams every day.', 'An analyst role supports product decisions rather than owning them; a later move is still needed to own a product.', false, array['pm-bridges-v1:B1']::text[], '{"pm-bridges-v1:B1": "Responsibilities and base requirements of the Product Analyst (Intermediate) level"}'::jsonb, 'employer_stated', 'hypothesis', true, '{"C1": {"develops": "Learning about users through product data, segmentation and experiments.", "incomplete": "Direct research with users, and deciding what matters from it.", "seek": "Join the product manager''s discovery interviews and propose priorities from what you learn."}, "X5": {"develops": "Monetisation and revenue analysis.", "incomplete": "Owning a business case.", "seek": "Prepare the value case for one product decision."}}'::jsonb);
insert into public.trace_bridge_roles (catalogue_version, target_role_id, bridge_role_id, requirements_pack, responsibilities, develops, partly_develops, develops_note, entry_basis, entry_requirements_stated, entry_signal_families, entry_signal_requirements, suitable_backgrounds, suitability_note, tradeoff_note, level_step, source_keys, source_notes, entry_evidence, progression_evidence, may_be_primary, partial_development)
values ('pm-bridges-v2', 'PM-PM', 'ROLE-OWNER', 'pm-v1.2', array['Is accountable for maximising the value of the product resulting from the team''s work', 'Develops and communicates the Product Goal', 'Creates and communicates backlog items and orders the backlog', 'Keeps the backlog transparent and understood; stakeholders who want changes must convince the Product Owner']::text[], array['C3', 'C5', 'C6']::text[], array['C2']::text[], 'Develops turning problems into requirements and priorities (C3), stakeholder communication (C5) and iterative delivery (C6). The Product Goal is a step towards product direction (C2, partly). Discovery (C1) and outcome metrics (C4) are not part of the accountability as defined.', 'signals', 'The Scrum Guide states no entry requirements. Business Analyst to Product Owner and Product Owner to Product Manager are curated hypotheses (D34): the source supports the responsibilities, not the career moves.', array['business_analysis']::text[], array['C3']::text[], 'Business analysis, or any background with demonstrated or transferable requirements and prioritisation work.', 'Suits someone whose gaps are in owning priorities and delivery with a team, and who already writes or works with requirements.', 'Employers use ''Product Owner'' in different ways; some roles are backlog administration with little product direction. Check the responsibilities of a specific role.', false, array['pm-bridges-v1:B2']::text[], '{"pm-bridges-v1:B2": "The Product Owner accountability, Product Goal and Product Backlog"}'::jsonb, 'hypothesis', 'hypothesis', false, '{"C2": {"develops": "Developing and communicating the Product Goal for one product.", "incomplete": "Product strategy and a roadmap beyond the current goal.", "seek": "Ask to set the roadmap beyond the current Product Goal, with the people who own the product''s strategy."}}'::jsonb);
