values ('pm-bridges-v2', 'PM-SPM', 'PM-PM', 'pm-v1.2', array['Owns a product or product area end to end: discovery, direction, priorities, delivery and outcomes', 'Defines and tracks the product''s success measures', 'Works across functions and with stakeholders on the product''s decisions']::text[], array['C1', 'C2', 'C3', 'C4', 'C5', 'C6']::text[], array['L2', 'L3', 'L4']::text[], 'F1: a product manager works at ''practitioner'' level in user insight, product management, stakeholder relationships and agile practice, and ''working'' in strategic ownership, managing outcomes and product leadership. All core requirements are developed; senior differentiators only partly. Portfolio scope (L1) is not developed.', 'target_assessment', 'Assessed with the Product Manager requirements of the approved pack; employers set their own criteria.', '{}'::text[], '{}'::text[], 'Anyone moving into product management for the first time who aims at a senior level.', 'Suits someone without product management experience who targets Senior Product Manager: the frameworks place Product Manager as the level before it.', 'One more move before the senior level.', true, array['pm-v1:F1', 'pm-v1:F4']::text[], '{"pm-v1:F1": "Role levels: product manager, then senior product manager", "pm-v1:F4": "Job family levels: P3 Product Manager, then P4 Senior Product Manager"}'::jsonb, 'target_plan', 'source_stated', true, '{"L2": {"develops": "Product leadership at working level (F1).", "incomplete": "Coaching and leading other product practitioners.", "seek": "Mentor an associate or a newer product manager."}, "L3": {"develops": "Presenting your product''s decisions to stakeholders.", "incomplete": "Regular communication with senior leaders.", "seek": "Present your product''s progress and risks to senior leaders."}, "L4": {"develops": "Coordinating your product''s dependencies.", "incomplete": "Planning across several teams.", "seek": "Lead the planning of one initiative that spans several teams."}}'::jsonb);

