insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'build.C1', 'pm-v1.2', 1, 'build', 'C1', 'Understand how product teams learn what users need', 'Study how the cited frameworks describe user-centred insight, then plan five short interviews with users or internal customers of something you work on, with the questions you would ask and what decision each answer could change.', 'A one-page research plan: who you will speak to, your questions, and the decisions they inform (a learning exercise, not professional evidence)', array['self_directed_study', 'current_job']::text[], array['pm-v1:F1']::text[], array['learning_exercise']::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'demonstrate.C1', 'pm-v1.2', 2, 'demonstrate', 'C1', 'Show that you learn from users and act on it', 'Run the interviews (or analyse existing feedback or support tickets), summarise what users need, and propose one change based on it to the people who decide.', 'An insight summary with the proposed change and what happened to it. If you do this as a personal project, label it as a personal project, not professional product ownership.', array['current_job', 'internal_move', 'external_project']::text[], array['pm-v1:F1']::text[], array['personal_project_possible']::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'build.C2', 'pm-v1.2', 1, 'build', 'C2', 'Understand how a product direction becomes a sequenced roadmap', 'Study how the cited frameworks describe roadmapping and strategic ownership, then write a short product direction for a product you know: the problem, who it is for, and three outcomes in priority order.', 'A one-page product direction with a sequenced, outcome-based roadmap (a learning exercise, not professional evidence)', array['self_directed_study']::text[], array['pm-v1:F1', 'pm-v1:F4']::text[], array['learning_exercise']::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'demonstrate.C2', 'pm-v1.2', 2, 'demonstrate', 'C2', 'Show that you can set and sequence direction for a product area', 'Offer to draft the next-quarter priorities for a feature area or internal tool you work on, explain the order you chose, and get it reviewed by the person who owns the area.', 'A roadmap draft you prepared for one area, reviewed by the area''s owner (a contribution, not ownership). If you do this as a personal project, label it as a personal project, not professional product ownership.', array['current_job', 'internal_move', 'external_project']::text[], array['pm-v1:F1']::text[], array['personal_project_possible']::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'build.C3', 'pm-v1.2', 1, 'build', 'C3', 'Learn to turn a problem into clear requirements and priorities', 'Take a problem you have seen at work and write it up as a problem statement, user stories with acceptance criteria, and a short reason for their order.', 'A written problem statement with prioritised user stories and acceptance criteria (a learning exercise, not professional evidence)', array['self_directed_study', 'current_job']::text[], array['pm-v1:F1', 'pm-bridges-v1:B2']::text[], array['learning_exercise']::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'demonstrate.C3', 'pm-v1.2', 2, 'demonstrate', 'C3', 'Show that your requirements and priorities are used by a team', 'Write the requirements for one real piece of work your team takes on, agree the priority order with the team, and follow it through to delivery.', 'Requirements a team built from, with the agreed order and the delivered result', array['current_job', 'internal_move']::text[], array['pm-v1:F1']::text[], '{}'::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'build.C4', 'pm-v1.2', 1, 'build', 'C4', 'Understand how product outcomes are defined and measured', 'Study how the cited frameworks describe managing product outcomes, then pick a feature you know and define its outcome, one success metric, its baseline and how you would read the result.', 'A one-page metric definition: outcome, metric, baseline and decision rule (a learning exercise, not professional evidence)', array['self_directed_study']::text[], array['pm-v1:F1']::text[], array['learning_exercise']::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'demonstrate.C4', 'pm-v1.2', 2, 'demonstrate', 'C4', 'Show that you own an outcome metric and decide from it', 'Agree a success metric for one feature or process change in your team before it ships, track it afterwards, and write up what it showed and what was decided.', 'A before-and-after metric review with the decision it led to. If you do this as a personal project, label it as a personal project, not professional product ownership.', array['current_job', 'internal_move', 'external_project']::text[], array['pm-v1:F1']::text[], array['personal_project_possible']::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
