insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'demonstrate.C5', 'pm-v1.2', 2, 'demonstrate', 'C5', 'Show that you lead cross-functional decisions', 'Facilitate one decision that involves at least two other functions (for example engineering and sales): prepare the options, run the discussion, and circulate the decision and its reasons.', 'A written decision record with the options, the outcome and who agreed', array['current_job', 'internal_move']::text[], array['pm-v1:F1']::text[], '{}'::text[]);
insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
