insert into public.trace_action_templates (template_version, template_key, requirements_pack, stage, kind, requirement_key, objective, action_text, deliverable, where_options, basis_sources, labels)
values ('pm-actions-v2', 'demonstrate.C6', 'pm-v1.2', 2, 'demonstrate', 'C6', 'Show that you run iterative delivery', 'Take one piece of work through at least two increments with your team, reviewing what was learned after each before deciding the next.', 'Short review notes for each increment and the change they led to. If you do this as a personal project, label it as a personal project, not professional product ownership.', array['current_job', 'internal_move', 'external_project']::text[], array['pm-v1:F1']::text[], array['personal_project_possible']::text[]);
