-- ------------------------------------------------------------------ employer criterion rules v2 (one per stored criterion)
do $$
declare n integer;
begin
  insert into public.trace_employer_criterion_rules (rules_version, requirement_id, rule)
  select 'pm-eligibility-v2', r.requirement_id, '{"all": [{"equivalent_families": ["product_ownership", "entrepreneurship"], "families": ["product_management"], "max": null, "min": 6, "type": "years_in_families"}, {"text": "at least 2 years focused on growth or product-led growth", "type": "stated_condition"}]}'::jsonb
    from public.trace_target_role_requirements r join public.trace_target_role_sources s using (target_role_source_id)
   where s.source_key = 'pm-v1:J2' and r.requirement_text = '6+ years of product management, at least 2 focused on growth or PLG';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'D36: expected one criterion for J2, found %', n; end if;
end
$$;
do $$
declare n integer;
begin
  insert into public.trace_employer_criterion_rules (rules_version, requirement_id, rule)
  select 'pm-eligibility-v2', r.requirement_id, '{"all": [{"equivalent_families": ["product_ownership", "entrepreneurship"], "families": ["product_management"], "max": 8, "min": 4, "type": "years_in_families"}, {"text": "at least 2 years owning a platform, API or infrastructure product", "type": "stated_condition"}]}'::jsonb
    from public.trace_target_role_requirements r join public.trace_target_role_sources s using (target_role_source_id)
   where s.source_key = 'pm-v1:J3' and r.requirement_text = '4 to 8 years of product management, at least 2 owning a platform, API or infrastructure product';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'D36: expected one criterion for J3, found %', n; end if;
end
$$;
do $$
declare n integer;
begin
  insert into public.trace_employer_criterion_rules (rules_version, requirement_id, rule)
  select 'pm-eligibility-v2', r.requirement_id, '{"families": ["software_engineering"], "max": null, "min": 2, "note": "A preference in addition to the product management experience, not a substitute for it.", "type": "years_in_families"}'::jsonb
    from public.trace_target_role_requirements r join public.trace_target_role_sources s using (target_role_source_id)
   where s.source_key = 'pm-v1:J3' and r.requirement_text = 'A computer science or engineering degree is not mandatory; ideally 2+ years as an engineer or architect before product';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'D36: expected one criterion for J3, found %', n; end if;
end
$$;
do $$
declare n integer;
begin
  insert into public.trace_employer_criterion_rules (rules_version, requirement_id, rule)
  select 'pm-eligibility-v2', r.requirement_id, '{"all": [{"equivalent_families": ["product_ownership", "entrepreneurship"], "families": ["product_management"], "max": 8, "min": 4, "type": "years_in_families"}, {"text": "strong product management experience with ownership from concept to launch and scale", "type": "stated_condition"}]}'::jsonb
    from public.trace_target_role_requirements r join public.trace_target_role_sources s using (target_role_source_id)
